// Real promo cards (core/realpromos.js, GENERATED by tools/build_real_promos.py from data/promo_cards): every row becomes a card that
// is a special version of an existing real base card (same person, photo, nation, PlayStyles + one upgrade) with the REAL promo rating,
// six face stats, position, skill moves, weak foot and real club. DOM-free, no shared RNG, no hotlinked image (the card shows the base
// player's local photo or the SVG avatar). Ids `rc<yy>_<eaId>` (never touched by old saves). They are appended after every other card
// (players.js) and are NOT in db.promos, so the older SBC / promo-reward logic that reads db.promos stays as it was; they are in db.all
// with `special` = the campaign id of their family (core/promos.js), so campaign release weeks, promo packs and `promo_<id>` pools apply.
import { clamp } from './rng.js';
import { REAL_PROMO_FAMILIES, REAL_PROMO_ROWS } from './realpromos.js';
import { PROMO_BY_ID, upgradeStyles } from './promos.js';

const FACE = ['pac', 'sho', 'pas', 'dri', 'def', 'phy'];
const GKFACE = ['div', 'han', 'kic', 'ref', 'spd', 'pos'];

/** helpers = { byId (Map of card id -> card), computeOvr, tierOf, marketValue }. Returns the new cards (rows whose base is missing are skipped). */
export function buildRealPromoCards({ byId, computeOvr, tierOf, marketValue }) {
  const out = [];
  for (const [eaId, game, fi, baseId, ovr, pos, alt, face, sm, wf, club, league] of REAL_PROMO_ROWS) {
    const base = byId.get(baseId);
    const [famName, campaign] = REAL_PROMO_FAMILIES[fi];
    if (!base || !PROMO_BY_ID[campaign]) continue;
    const p = structuredClone(base);
    p.id = `rc${game}_${eaId}`;
    p.baseId = base.id;
    delete p.intended; delete p.era; delete p.totw; delete p.upg; delete p.photoDyn;
    const gk = pos === 'GK';
    const keys = gk ? GKFACE : FACE;
    const src = gk ? p.gk : p.stats;
    keys.forEach((k, i) => { src[k] = face[i]; });
    if (gk) p.stats.pac = face[4];
    else p.gk.spd = face[0];
    p.pos = pos; p.alt = alt.slice();
    p.sm = gk ? 1 : clamp(sm, 1, 5); p.wf = clamp(wf, 1, 5);
    delete p.ob;
    const raw = computeOvr(pos, p);
    if (raw !== ovr) p.ob = clamp(ovr - raw, -12, 12); // EA's overall uses hidden attributes: keep the real overall, store the difference
    p.ovr = computeOvr(pos, p);
    p.pot = Math.max(p.pot || p.ovr, p.ovr);
    p.special = campaign; p.promo = campaign; p.rare = true; p.tier = tierOf(p.ovr);
    p.realPromo = { name: famName, game }; // the real EA promo this card is (UI may show it)
    p.futId = eaId;
    if (club) p.realClub = club;
    if (league) p.realLeague = league;
    if (base.special === 'lotg' || base.club === 'ICN') p.linkAll = true; // keeps the LOTG chemistry perks
    upgradeStyles(p, 1);
    p.value = marketValue({ ...p, age: Math.min(p.age, 30) }) * 2;
    p.look = base.look;
    out.push(p);
  }
  return out;
}
